// Only these ESPN services can be reached; callers cannot provide upstream URLs.
const SPORT_SERVICES={nba:{path:'basketball/nba',fantasy:'fba',bench:[12,13],positions:{1:'PG',2:'SG',3:'SF',4:'PF',5:'C'},slots:{0:'PG',1:'SG',2:'SF',3:'PF',4:'C',5:'G',6:'F',7:'SG/SF',8:'G/F',9:'PF/C',10:'F/C',11:'UTIL',12:'BE',13:'IR',15:'Rookie'}},nhl:{path:'hockey/nhl',fantasy:'fhl',bench:[7,8],positions:{1:'C',2:'LW',3:'RW',4:'D',5:'G'},slots:{0:'C',1:'LW',2:'RW',3:'F',4:'D',5:'G',6:'UTIL',7:'BE',8:'IR',10:'SK'}},mlb:{path:'baseball/mlb',fantasy:'flb',bench:[16,17],positions:{1:'SP',2:'C',3:'1B',4:'2B',5:'3B',6:'SS',7:'LF',8:'CF',9:'RF',10:'DH',11:'RP'},slots:['C','1B','2B','3B','SS','OF','2B/SS','1B/3B','LF','CF','RF','DH','UTIL','P','SP','RP','BE','IL']}};
const sportJSON=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
