  const title=String(item.name||item.title||''),url=publicPlayerURL(item.url,'https://streamcorner.st');
  const raw=item.startDate??item.start??item.date,start=typeof raw==='number'?(raw<1e12?raw*1000:raw):Date.parse(raw);
